#define main original_pagerank_main
#include "../page-rank-cuda/main.cu"
#undef main
#include <vector>
#include <set>
#include <algorithm>
#include <string>
const int N=257,ITERS=64;
struct Case{std::vector<int>pages;std::vector<unsigned>degrees;std::vector<std::vector<int>>edges;std::vector<float>expected;int*p;unsigned*degree;float*rank,*map,*history;};
int main(){std::vector<Case>cases;for(bool irregular:{false,true}){Case c;c.pages.resize(N*N,0);c.degrees.resize(N);c.edges.resize(N);for(int i=0;i<N;i++){std::set<int>targets=irregular?std::set<int>{(i+1)%N,(i+13)%N,(17*i+5)%N}:std::set<int>{(i+1)%N,(i+13)%N,(i+37)%N};if(irregular){if(i%3==0)targets.insert((i+37)%N);if(i!=0)targets.insert(0);targets.erase(i);}for(int j:targets){c.pages[i*N+j]=1;c.edges[i].push_back(j);}c.degrees[i]=targets.size();}std::vector<double>rank(N,double(1.f/float(N))),old=rank,hist(N,0),trajectory;double d=double(.85f),tele=double((1.f-.85f)/float(N));for(int it=0;it<ITERS;it++){old=rank;std::vector<double>incoming(N,0);for(int i=0;i<N;i++)for(int j:c.edges[i])incoming[j]+=old[i]/c.degrees[i];for(int j=0;j<N;j++){rank[j]=tele+d*incoming[j];hist[j]=std::max(hist[j],std::abs(rank[j]-old[j]));}trajectory.insert(trajectory.end(),rank.begin(),rank.end());}for(int i=0;i<N;i++)for(int j=0;j<N;j++)c.expected.push_back(float(c.pages[i*N+j]*(old[i]/c.degrees[i])));for(double x:trajectory)c.expected.push_back(float(x));for(double x:hist)c.expected.push_back(float(x));cudaMalloc(&c.p,N*N*4);cudaMalloc(&c.degree,N*4);cudaMalloc(&c.rank,N*4);cudaMalloc(&c.map,N*N*4);cudaMalloc(&c.history,N*4);cudaMemcpy(c.p,c.pages.data(),N*N*4,cudaMemcpyHostToDevice);cudaMemcpy(c.degree,c.degrees.data(),N*4,cudaMemcpyHostToDevice);cases.push_back(c);}
 auto run=[&](Case&c,bool emit,std::vector<float>&got,double&total,double&error){std::vector<float>initial(N,1.f/float(N)),history(N),one(N),trajectory,fullmap(N*N);cudaMemcpy(c.rank,initial.data(),N*4,cudaMemcpyHostToDevice);cudaMemset(c.history,0,N*4);for(int it=0;it<ITERS;it++){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();map<<<2,256>>>(c.p,c.rank,c.map,c.degree,N);reduce<<<2,256>>>(c.rank,c.map,N,c.history);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();cudaMemcpy(history.data(),c.history,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(one.data(),c.rank,N*4,cudaMemcpyDeviceToHost);trajectory.insert(trajectory.end(),one.begin(),one.end());}cudaMemcpy(fullmap.data(),c.map,N*N*4,cudaMemcpyDeviceToHost);std::vector<float>output=fullmap;output.insert(output.end(),trajectory.begin(),trajectory.end());output.insert(output.end(),history.begin(),history.end());for(size_t i=0;i<output.size();i++)error=std::max(error,std::abs(double(output[i])-c.expected[i]));got.insert(got.end(),output.begin(),output.end());};
 {std::vector<float>discard;double total=0,error=0;for(auto&c:cases)run(c,false,discard,total,error);}
 for(int trial=1;trial<=5;trial++){std::vector<float>got;double total=0,error=0;for(auto&c:cases)run(c,true,got,total,error);bool ok=error<1e-6&&std::all_of(got.begin(),got.end(),[](float v){return std::isfinite(v);});std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(got.data(),4,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":165508,\"max_abs_error\":%.17g,\"timing_region\":\"sum_two_graphs_64_periteration_map_reduce_sync_totals\",\"jit_excluded\":true,\"internal_repeats\":64,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":165508,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",error,path.c_str());if(!ok)return 9;}}
